const rows = $('Get Cases').all().map(i => i.json);

if (rows.length === 0) {
  return [{ json: { table: 'cases', count: 0, cases: [], summary: 'No eval cases found.' } }];
}

return [{ json: {
  table: 'cases',
  count: rows.length,
  cases: rows.map(r => {
    const ec = typeof r.eval_config === 'string' ? JSON.parse(r.eval_config || '{}') : (r.eval_config || {});
    const inputs = typeof r.inputs === 'string' ? JSON.parse(r.inputs || '{}') : (r.inputs || {});
    return {
      case_id: r.case_id,
      input: (inputs.prompt || '').substring(0, 200),
      expected_tools: ec.expected_tools || '',
      prohibited_tools: ec.prohibited_tools || '',
      source_thread: ec.source_thread || '',
      created_at: r.created_at
    };
  }),
  summary: rows.length + ' eval cases loaded.'
} }];

const input = $('Input').first().json;
const allRows = $('Get Results').all().map(i => i.json);

let rows = allRows;
if (input.run_id) {
  rows = rows.filter(r => String(r.run_id) === String(input.run_id));
}
if (input.case_id) {
  rows = rows.filter(r => String(r.case_id) === String(input.case_id));
}

if (rows.length === 0) {
  return [{ json: { table: 'results', count: 0, results: [], summary: 'No results found.' + (input.run_id ? ' Run may still be in progress.' : '') } }];
}

function getScore(r) {
  return typeof r.score === 'string' ? JSON.parse(r.score || '{}') : (r.score || {});
}

const verdicts = rows.reduce((acc, r) => { const v = r.status || getScore(r).verdict || 'unknown'; acc[v] = (acc[v] || 0) + 1; return acc; }, {});
const dims = ['faithfulness', 'citation_validity', 'source_routing', 'completeness', 'relevance', 'format'];
const avgScores = {};
dims.forEach(d => {
  const vals = rows.map(r => parseFloat(getScore(r)[d])).filter(v => !isNaN(v));
  avgScores[d] = vals.length ? (vals.reduce((a,b) => a+b, 0) / vals.length).toFixed(2) : 'N/A';
});

return [{ json: {
  table: 'results',
  count: rows.length,
  stats: { verdicts, avg_scores: avgScores },
  results: rows.map(r => {
    const score = getScore(r);
    return {
      run_id: r.run_id, case_id: r.case_id, verdict: r.status || score.verdict,
      faithfulness: score.faithfulness, citation_validity: score.citation_validity,
      source_routing: score.source_routing, completeness: score.completeness,
      relevance: score.relevance, format: score.format,
      instance: r.instance, run_date: r.run_date
    };
  }),
  summary: rows.length + ' results: ' + (verdicts.pass || 0) + ' pass, ' + (verdicts.borderline || 0) + ' borderline, ' + (verdicts.fail || 0) + ' fail'
} }];
